  &reftitle.examples;

   Exemplo do método DateTime::getTimezone

&style.oop;


<?php
$date = new DateTimeImmutable("now", new DateTimeZone('Europe/London'));
$tz = $date->getTimezone();
echo $tz->getName();


   &example.outputs;


Europe/London



&style.procedural;


<?php
$date = date_create("now", timezone_open('Europe/London'));
$tz = date_timezone_get($date);
echo timezone_name_get($tz);


   &example.outputs;


Europe/London
